	}
	if waiterErr != nil {
		t.Errorf("waiter goroutine: %v", waiterErr)
	}

	// Verify no stale entry.
	cache.mu.Lock()
	_, hasStale := cache.loading["key"]
	cache.mu.Unlock()

	if hasStale {
		t.Error("c.loading[\"key\"] still present — stale entry leak")
	}
